@pytest.mark.parametrize("expr,want", PROBES)
def test_desktop(expr, want):
    try:
        got = de.DAXEngine()._eval_expr(expr, de.DAXContext(MODEL, {}))
    except Exception:
        got = "ERR"
    if isinstance(got, float) and got.is_integer():
        got = int(got)
    assert str(got) == want
